interface.definition:
a!localVariables(
  {
    /* ── TITLE BAR ── */
    #"SYSTEM_SYSRULES_cardLayout"(
      contents: {
        #"SYSTEM_SYSRULES_sideBySideLayout"(
          alignVertical: "MIDDLE",
          items: {
            /* Icon */
            #"SYSTEM_SYSRULES_sideBySideItem"(
              width: "MINIMIZE",
              item: #"SYSTEM_SYSRULES_richTextDisplayField"(
                marginBelow: "NONE",
                labelPosition: "COLLAPSED",
                value: {
                  #"SYSTEM_SYSRULES_richTextIcon"(
                    icon: "th-large",
                    size: "MEDIUM_PLUS"
                  )
                }
              )
            ),
            /* Page Title */
            #"SYSTEM_SYSRULES_sideBySideItem"(
              item: #"SYSTEM_SYSRULES_headingField"(
                marginBelow: "NONE",
                text: "Application Management",
                fontWeight: "SEMI_BOLD",
                size: "MEDIUM",
                headingTag: "H1"
              )
            ),
            /* Primary Action Button */
            #"SYSTEM_SYSRULES_sideBySideItem"(
              width: "MINIMIZE",
              item: #"SYSTEM_SYSRULES_recordActionField_v1"(
                actions: #"SYSTEM_SYSRULES_recordActionItem"(
                  action: #"urn:appian:record-action:v1:d82b71ee-1dd1-46f0-ba3e-d6849d0512f7/2cde0a1f-ad73-4eb1-8188-8d6a183712f0"
                ),
                style: "CALL_TO_ACTION",
                align: "END"
              )
            )
          }
        )
      },
      height: "AUTO",
      style: "ACCENT",
      padding: "STANDARD",
      marginBelow: "NONE",
      showBorder: false
    ),

    /* ── CONTENT AREA ── */
    #"SYSTEM_SYSRULES_columnsLayout"(
      columns: {

        /* ── LEFT: Application Grid ── */
        #"SYSTEM_SYSRULES_columnLayout"(
          contents: {
            #"SYSTEM_SYSRULES_cardLayout"(
              contents: {
                #"_a-0000eef8-4604-8000-9e54-011c48011c48_1136318"(
                  appid: null()
                )
              },
              height: "AUTO",
              style: "NONE",
              shape: "SEMI_ROUNDED",
              padding: "STANDARD",
              marginBelow: "STANDARD",
              showBorder: false,
              showShadow: true
            )
          }
        )

      }
    )
  }
)
